## Query

PHQL queries can be created by instantiating the class [Phalcon\Mvc\Model\Query][mvc-model-query]:

```php
<?php

use Phalcon\Mvc\Model\Query;

$container = Di::getDefault();
$query     = new Query(
    'SELECT * FROM Invoices',
    $container
);

$invoices = $query->execute();
```

The [Phalcon\Mvc\Model\Query][mvc-model-query] requires the second parameter of the constructor to be the DI container. When calling the above code from a controller or any class that extends the [Phalcon\Di\Injectable][di-injectable], you can use:

```php
<?php

use Phalcon\Di\Di;
use Phalcon\Mvc\Controller;
use Phalcon\Mvc\Model\Query;
use Phalcon\Mvc\View;

/**
 * @property Di   $di
 * @property View $view
 */
class Invoices extends Controller
{
    public function listAction()
    {
        $query = new Query(
            'SELECT * FROM Invoices',
            $this->di
        );

        $invoices = $query->execute();

        $this->view->setVar('invoices', $invoices);
    }
}
```

public function __destruct()
    {
        phalcon_orm_destroy_cache();

        Query::clean();
    }

public function executeQuery( string phql, var placeholders = null, var types = null) -> var
    {
        var query;

        let query = this->createQuery(phql);

        if typeof placeholders == "array" {
            query->setBindParams(placeholders);
        }

        if typeof types == "array" {
            query->setBindTypes(types);
        }

        /**
         * Execute the query
         */
        return query->execute();
    }

public function execute(array bindParams = [], array bindTypes = [])
    {
        var adapter, cache, cacheLifetime, cacheOptions, cacheService,
            defaultBindParams, defaultBindTypes, intermediate, key, lifetime,
            mergedParams, mergedTypes, preparedResult, result, type, uniqueRow;

        let uniqueRow    = this->uniqueRow,
            cacheOptions = this->cacheOptions;

public function execute() -> bool
    {
        let this->rowCount = null;
        return this->pdoStatement->execute();
    }

public function execute( string sqlStatement,  array bindParams = [],  array bindTypes = []) -> bool
    {
        var eventsManager, affectedRows, e;

        /**
         * Execute the beforeQuery event if an EventsManager is available
         */
        let eventsManager = <ManagerInterface> this->eventsManager;
        if typeof eventsManager == "object" {
            let this->sqlStatement = sqlStatement,
                this->sqlVariables = bindParams,
                this->sqlBindTypes = bindTypes;

            if eventsManager->fire("db:beforeQuery", this) === false {
                return false;
            }
        }

        /**
         * Initialize affectedRows to 0
         */
        let affectedRows = 0;

        this->prepareRealSql(sqlStatement, bindParams);

        try {
            let affectedRows = this->executeStatement(sqlStatement, bindParams, bindTypes);
        } catch \PDOException, e {
            if !this->canReconnect(e) {
                throw e;
            }

            this->handleConnectionLost();

            let affectedRows = this->executeStatement(sqlStatement, bindParams, bindTypes);
        }

        /**
         * Execute the afterQuery event if an EventsManager is available
         */
        if typeof affectedRows == "integer" {
            let this->affectedRows = affectedRows;

            if typeof eventsManager == "object" {
                eventsManager->fire("db:afterQuery", this);
            }
